      followUpQuestions: ["How would you evaluate a fraud-detection model?", "What is early stopping?", "Why do tree models not usually require feature scaling?"],
      tags: ["machine-learning", "calibration"],
      seoTitle: "What is calibration? | Machine Learning Interview Question",
      seoDescription: "A classifier is calibrated when predicted probabilities correspond reasonably to observed frequencies",
      isPublished: true,
